From 44e56362ead2d3d9c59fdeae87f45797c19ce80b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:12:08 +0100
Subject: [PATCH] window: don't warp the pointer for move requests during a
 drag

A move requested through plasma-window-management always warped the
pointer to the window's center, so a drag from a panel grabbed the
window in the middle. With a button held, grab its top edge instead.

BUG: 433072
---
 src/window.cpp | 6 ++++++
 1 file changed, 6 insertions(+)

diff --git a/src/window.cpp b/src/window.cpp
index 214e2d7671..4fcaed8587 100644
--- a/src/window.cpp
+++ b/src/window.cpp
@@ -1846,6 +1846,12 @@ void Window::setupWindowManagementInterface()
         closeWindow();
     });
     connect(w, &PlasmaWindowInterface::moveRequested, this, [this]() {
+        if (input()->pointer()->areButtonsPressed()) {
+            // The request comes from a drag, e.g. on a panel: grab the window by its top edge where the pointer is
+            const RectF frame = frameGeometry();
+            performMousePressCommand(Options::MouseMove, QPointF(std::clamp(Cursors::self()->mouse()->pos().x(), frame.left(), frame.right()), frame.top()));
+            return;
+        }
         input()->pointer()->warp(frameGeometry().center());
         performMousePressCommand(Options::MouseMove, Cursors::self()->mouse()->pos());
     });
-- 
