From 1b8dc97eb830a81b203c186c6470a218008ff157 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:12:08 +0100
Subject: [PATCH] containments/panel: drag maximized windows from empty top
 panel space

With borderless maximized windows there is no titlebar to grab, and
dragging the empty space of a top panel did nothing. Now it starts
moving the maximized active window on that screen, like its titlebar.

BUG: 433072
---
 containments/panel/main.qml | 33 +++++++++++++++++++++++++++++++++
 1 file changed, 33 insertions(+)

diff --git a/containments/panel/main.qml b/containments/panel/main.qml
index 4ee220333e..e9c9dc47a3 100644
--- a/containments/panel/main.qml
+++ b/containments/panel/main.qml
@@ -15,6 +15,7 @@ import org.kde.ksvg as KSvg
 import org.kde.plasma.components as PC3
 import org.kde.draganddrop as DragDrop
 import org.kde.kirigami as Kirigami
+import org.kde.taskmanager as TaskManager

 import "LayoutManager.js" as LayoutManager

@@ -156,6 +157,38 @@ ContainmentItem {
         onLongPressed: Plasmoid.internalAction("configure").trigger()
     }

+    TaskManager.TasksModel {
+        id: tasksModel
+        filterByScreen: true
+        screenGeometry: root.Plasmoid.containment.screenGeometry
+        groupMode: TaskManager.TasksModel.GroupDisabled
+    }
+
+    // Dragging empty space of a top panel moves the maximized window below it, like dragging its titlebar
+    DragHandler {
+        enabled: Plasmoid.location === PlasmaCore.Types.TopEdge && !Containment.corona.editMode
+        target: null
+        acceptedButtons: Qt.LeftButton
+        acceptedDevices: PointerDevice.Mouse | PointerDevice.TouchPad
+        onActiveChanged: {
+            if (!active) {
+                return;
+            }
+            const pos = currentLayout.mapFromItem(root, centroid.pressPosition);
+            const container = currentLayout.childAt(pos.x, pos.y) as AppletContainer;
+            if (container && container.applet?.plasmoid?.pluginName !== "org.kde.plasma.panelspacer") {
+                return;
+            }
+            const task = tasksModel.activeTask;
+            if (task.valid && tasksModel.data(task, TaskManager.AbstractTasksModel.IsMaximized)) {
+                tasksModel.requestMove(task);
+                // KWin takes over the pointer, so the button release never reaches the panel. This makes
+                // Qt release the button itself; it can't move the panel, which is a layer-shell surface
+                root.Window.window.startSystemMove();
+            }
+        }
+    }
+
     DragDrop.DropArea {
         id: dropArea
         anchors.fill: parent
-- 
